// Browser end-to-end acceptance on the REAL stack (see e2e/server.py): Microsoft Edge → built Vue app → FastAPI →
// Alembic SQLite → background jobs → BM25 (+ bge-m3 Dense if installed) → local Ollama qwen2.5:7b via SSE.
// Fictional business scenario "星河制造"; documents are generated by the server script (synthetic only).
import { expect, test, type Browser, type Page } from '@playwright/test'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
const __dirname = path.dirname(fileURLToPath(import.meta.url))

const run = () => JSON.parse(readFileSync(path.resolve(__dirname, '..', '.e2e', 'run.json'), 'utf-8'))
const ADMIN = { u: 'e2e_admin', p: process.env.KB_E2E_ADMIN_PASSWORD! }
const RND = { u: 'rnd_li', p: process.env.KB_E2E_USER_PASSWORD! }
const HR = { u: 'hr_wang', p: process.env.KB_E2E_USER_PASSWORD! }
const KB = '星河制造知识库'
const FILES = ['研发发布规范.md', '薪酬管理制度.docx', '公司假期安排.txt', 'Quality_Audit_Report.pdf']

async function login(page: Page, who: { u: string; p: string }) {
  await page.goto('/login')
  await page.getByTestId('login-username').fill(who.u)
  await page.getByTestId('login-password').fill(who.p)
  await page.getByTestId('login-submit').click()
  await page.waitForURL(/\/chat/)
}
async function newPage(browser: Browser) { return (await browser.newContext()).newPage() }
async function pickOption(page: Page, testId: string, text: string) {
  await page.getByTestId(testId).click()
  await page.locator('.el-select-dropdown__item:visible', { hasText: new RegExp(`^${text}$`) }).first().click()
  await page.keyboard.press('Escape')
}
async function token(page: Page) { return page.evaluate(() => sessionStorage.getItem('kb.token')) }

/** Ask through the UI; wait for the SSE request and for the final answer of this turn. */
async function ask(page: Page, q: string) {
  const turns = page.getByTestId('turn')
  const before = await turns.count()
  const streamResp = page.waitForResponse((r) => r.url().includes('/ask/stream'))
  await page.getByTestId('chat-input').fill(q)
  await page.getByTestId('chat-send').click()
  const resp = await streamResp
  expect(resp.headers()['content-type']).toContain('text/event-stream')
  const turn = turns.nth(before)
  await expect(page.getByTestId('chat-send')).not.toHaveClass(/is-loading/, { timeout: 300_000 })   // stream finished
  await expect(turn.locator('.streaming')).toHaveCount(0)
  return turn
}

test('星河制造：管理员建库导入授权，员工流式问答，撤权/更新/退出后不泄漏', async ({ browser }) => {
  const files = run().files as Record<string, string>
  const admin = await newPage(browser)
  let kbUrl = ''

  await test.step('1-2 管理员登录并创建知识库', async () => {
    await login(admin, ADMIN)
    await admin.goto('/knowledge')
    await admin.getByTestId('kb-create-open').click()
    await admin.getByTestId('kb-name').fill(KB)
    await admin.getByTestId('kb-create').click()
    await admin.getByTestId('kb-card').filter({ hasText: KB }).click()
    await admin.waitForURL(/\/knowledge\/[0-9a-f]{32}/)
    kbUrl = admin.url()
  })

  await test.step('3-4 上传 PDF / DOCX / Markdown / TXT，查看解析与索引结果', async () => {
    await admin.getByTestId('open-upload').click()
    await admin.getByTestId('file-input').setInputFiles(FILES.map((f) => files[f]))
    await expect(admin.getByTestId('upload-table').locator('tbody tr')).toHaveCount(4)
    await admin.getByTestId('upload-start').click()
    await expect(admin.getByTestId('upload-progress')).toBeVisible()
    for (const f of FILES) {
      await expect(admin.getByTestId('upload-table').locator('tr', { hasText: f })).toContainText('已索引', { timeout: 600_000 })
    }
    await admin.keyboard.press('Escape')
    await admin.reload()
    for (const f of FILES) await expect(admin.getByTestId(`vstatus-${f}`)).toHaveText('已索引')
    await expect(admin.getByTestId('index-badge')).toContainText('索引')
    // PDF chunks carry page numbers; the admin MANAGES but cannot READ (no grant yet)
    await admin.getByTestId('chunks-Quality_Audit_Report.pdf').click()
    await expect(admin.locator('.el-drawer.open')).toContainText('第 2 页')
    await expect(admin.locator('.el-drawer.open')).toContainText('没有阅读权限')
    await expect(admin.locator('.el-drawer.open')).not.toContainText('XH-QA-3141')
    await admin.keyboard.press('Escape')
  })

  await test.step('5 创建部门、角色和不同部门的用户', async () => {
    await admin.goto('/acl/departments')
    for (const [n, d] of [['rnd', '研发部'], ['hr', '人力资源部']]) {
      await admin.getByTestId('dept-name').fill(n)
      await admin.getByTestId('dept-desc').fill(d)
      await admin.getByTestId('dept-create').click()
      await expect(admin.getByTestId('dept-tree')).toContainText(n)
    }
    await admin.goto('/acl/roles')
    await admin.getByTestId('role-name').fill('quality_auditor')
    await admin.getByTestId('role-create').click()
    await expect(admin.locator('.el-table')).toContainText('quality_auditor')
    await admin.goto('/acl/users')
    for (const [who, dept] of [[RND, 'rnd'], [HR, 'hr']] as const) {
      await admin.getByTestId('user-create-open').click()
      await admin.getByTestId('user-username').fill(who.u)
      await admin.getByTestId('user-password').fill(who.p)
      await pickOption(admin, 'user-departments', dept)
      await admin.getByTestId('user-save').click()
      await expect(admin.getByTestId('user-table')).toContainText(who.u)
    }
  })

  await test.step('6 配置四维文档权限', async () => {
    await admin.goto(kbUrl)
    const setAcl = async (file: string, fn: () => Promise<void>) => {
      await admin.getByTestId(`acl-${file}`).click()
      await expect(admin.locator('.el-dialog:visible')).toContainText('默认拒绝')
      await fn()
      await admin.getByTestId('acl-save').click()
      await expect(admin.locator('.el-message--success').last()).toBeVisible()
    }
    await setAcl('研发发布规范.md', () => pickOption(admin, 'acl-allow-departments', 'rnd'))
    await setAcl('薪酬管理制度.docx', () => pickOption(admin, 'acl-allow-departments', 'hr'))
    await setAcl('公司假期安排.txt', () => admin.getByTestId('acl-global').click())
    await setAcl('Quality_Audit_Report.pdf', () => pickOption(admin, 'acl-allow-roles', 'quality_auditor'))
  })

  const user = await newPage(browser)
  let firstTurn: ReturnType<Page['locator']>
  await test.step('7-8 授权用户登录，实时流式答案与来源引用', async () => {
    await login(user, RND)
    await user.getByTestId('chat-new').click()
    await pickOption(user, 'chat-kb-select', KB)
    await user.getByTestId('chat-create').click()
    await user.waitForURL(/\/chat\/[0-9a-f]{32}/)
    firstTurn = await ask(user, '研发部发布前需要完成哪些检查？')
    const cards = firstTurn.getByTestId('citation-card')
    await expect(cards.first()).toBeVisible()
    await expect(cards.filter({ hasText: '研发发布规范.md' })).toHaveCount(1)
    await cards.filter({ hasText: '研发发布规范.md' }).click()
    await expect(user.getByTestId('source-text')).toContainText('XH-RND-7731')
    await user.keyboard.press('Escape')
  })

  await test.step('9 未授权内容不可见（同一用户问 HR 机密；HR 用户问研发文档）', async () => {
    const t = await ask(user, 'P3 等级的年度薪酬区间是多少？调薪什么时候进行？')
    await expect(t).not.toContainText('XH-HR-5520')
    await expect(t.getByTestId('citation-card').filter({ hasText: '薪酬管理制度' })).toHaveCount(0)
    const tok = await token(user)
    const docs = await (await user.request.get(`/api/v1/knowledge-bases/${kbUrl.split('/').pop()}/documents`, { headers: { Authorization: `Bearer ${tok}` } })).json()
    expect(docs.map((d: { original_filename: string }) => d.original_filename).sort()).toEqual(['公司假期安排.txt', '研发发布规范.md'])
    const hr = await newPage(browser)
    await login(hr, HR)
    await hr.getByTestId('chat-new').click()
    await pickOption(hr, 'chat-kb-select', KB)
    await hr.getByTestId('chat-create').click()
    const ht = await ask(hr, '研发部发布前需要完成哪些检查？')
    await expect(ht).not.toContainText('XH-RND-7731')
    await expect(ht.getByTestId('citation-card').filter({ hasText: '研发发布规范' })).toHaveCount(0)
    await hr.context().close()
  })

  await test.step('10 撤销权限后，缓存答案与旧引用不泄漏', async () => {
    await admin.goto(kbUrl)
    await admin.getByTestId('acl-研发发布规范.md').click()
    await admin.getByTestId('acl-allow-departments').locator('.el-tag__close').first().click()
    await admin.keyboard.press('Escape')
    await admin.getByTestId('acl-save').click()
    await expect(admin.locator('.el-message--success').last()).toBeVisible()
    const t = await ask(user, '研发部发布前需要完成哪些检查？')         // identical question: must not hit the old cache
    await expect(t).not.toContainText('XH-RND-7731')
    await expect(t.getByTestId('citation-card').filter({ hasText: '研发发布规范' })).toHaveCount(0)
    await firstTurn.getByTestId('citation-card').filter({ hasText: '研发发布规范.md' }).click()
    await expect(user.getByTestId('source-drawer')).toContainText('来源不可用')
    await user.keyboard.press('Escape')
    await user.reload()
    await expect(user.getByTestId('turn').first()).toContainText('内容已隐藏')
    await expect(user.locator('body')).not.toContainText('XH-RND-7731')
  })

  await test.step('11 文档更新后旧内容失效', async () => {
    await admin.goto(kbUrl)
    await admin.getByTestId('versions-公司假期安排.txt').click()
    await admin.locator('.el-drawer.open input[type=file]').setInputFiles(run().v2_holiday)
    await expect(admin.getByTestId('version-table').locator('tr', { hasText: 'v2' })).toContainText('已索引', { timeout: 300_000 })
    await expect(admin.getByTestId('version-table').locator('tr', { hasText: 'v1' })).toContainText('已被新版本替换')
    await admin.keyboard.press('Escape')
    const t = await ask(user, '入职满一年有几天年假？请假需要提前几天？')
    const card = t.getByTestId('citation-card').filter({ hasText: '公司假期安排.txt' })
    await expect(card.first()).toBeVisible()
    await card.first().click()
    await expect(user.getByTestId('source-text')).toContainText('XH-HOLIDAY-V2')
    await expect(user.getByTestId('source-text')).not.toContainText('XH-HOLIDAY-V1')
    await user.keyboard.press('Escape')
  })

  await test.step('12 退出登录后无法继续访问受保护接口', async () => {
    const tok = await token(user)
    expect(tok?.split('.').length).toBe(3)                               // JWT
    await user.getByTestId('user-menu').click()
    await user.getByTestId('logout').click()
    await user.waitForURL(/\/login/)
    const r = await user.request.get('/api/v1/sessions', { headers: { Authorization: `Bearer ${tok}` } })
    expect(r.status()).toBe(401)
    await user.goto('/chat')
    await user.waitForURL(/\/login/)
  })
})
